package dev.riye.toolscreen;

import dev.riye.toolscreen.mixin.MouseAccess;
import net.minecraft.client.Minecraft;

public final class ControlsProbe {
    private ControlsProbe(){}
    public static void camera(){Minecraft game=Minecraft.getInstance();double[] settings=NativeBridge.snapshot();double sensitivity=game.options.sensitivity().get();boolean smooth=game.options.smoothCamera,invertX=game.options.invertMouseX().get(),invertY=game.options.invertMouseY().get();float yaw=game.player.getYRot(),pitch=game.player.getXRot();MouseAccess mouse=(MouseAccess)game.mouseHandler;
        try{game.options.sensitivity().set(.5);game.options.smoothCamera=false;game.options.invertMouseX().set(false);game.options.invertMouseY().set(false);NativeBridge.set(128,1);NativeBridge.set(145,0);for(int mode=0;mode<5;mode++){NativeBridge.set(0,mode);NativeBridge.set(39,1.5);NativeBridge.set(38,1);turn(game,mouse,1.5,1.5);}NativeBridge.set(39,20);turn(game,mouse,20,20);NativeBridge.set(39,.12345678);turn(game,mouse,.12345678,.12345678);NativeBridge.set(0,3);NativeBridge.set(39,20);NativeBridge.set(146,.01234567);turn(game,mouse,.01234567,.01234567);NativeBridge.set(38,0);turn(game,mouse,.01234567,.01234567);NativeBridge.set(145,0);NativeBridge.set(38,0);turn(game,mouse,1,1);NativeBridge.set(38,1);NativeBridge.set(128,0);turn(game,mouse,1,1);Toolscreen.LOGGER.info("TOOLSCREEN_CAMERA_SCALING_PASS modes=5 maximum=20 unified=true eyeOverride=true precise=true disabled=true");}
        finally{for(int key:new int[]{0,39,40,38,128,145,146})NativeBridge.set(key,settings[key]);game.options.sensitivity().set(sensitivity);game.options.smoothCamera=smooth;game.options.invertMouseX().set(invertX);game.options.invertMouseY().set(invertY);mouse.toolscreenMouseX(0);mouse.toolscreenMouseY(0);game.player.setYRot(yaw);game.player.setXRot(pitch);}}
    private static void turn(Minecraft game,MouseAccess mouse,double horizontal,double vertical){horizontal=Math.max(.064,Math.min(4.096,horizontal));vertical=Math.max(.064,Math.min(4.096,vertical));game.player.setYRot(0);game.player.setXRot(0);game.player.yRotO=0;game.player.xRotO=0;mouse.toolscreenMouseX(8);mouse.toolscreenMouseY(4);mouse.toolscreenTurnPlayer(1.0/60);double yaw=game.player.getYRot(),pitch=game.player.getXRot();if(Math.abs(yaw-1.2*horizontal)>.0001||Math.abs(pitch-.6*vertical)>.0001)throw new IllegalStateException("Camera scaling mismatch: "+yaw+", "+pitch);}
    public static void beginPause(){NativeBridge.set(0,0);NativeBridge.set(99,1);NativeBridge.inputEvent(66,0,1,true,false);Minecraft.getInstance().pauseGame(true);Toolscreen.updateMeasurementPause();Toolscreen.hotkey(66,0,0);Toolscreen.hotkey(63,0,1);}
    public static void endPause(){Minecraft.getInstance().gui.setScreen(null);Toolscreen.updateMeasurementPause();NativeBridge.set(99,0);}
    public static void verifyPause(int stage){Minecraft game=Minecraft.getInstance();int[] view=Toolscreen.viewport();if(stage==20){if(!Toolscreen.measurementPaused()||Toolscreen.suspended()||NativeBridge.snapshot()[0]!=3||view[0]!=384||view[1]!=16384)throw new IllegalStateException("Measurement pause lost EyeZoom");Toolscreen.LOGGER.info("TOOLSCREEN_MEASUREMENT_PAUSE_PASS heldMode=true viewport={}x{}",view[0],view[1]);}if(stage==21){if(Toolscreen.measurementPaused()||Toolscreen.suspended()||NativeBridge.snapshot()[0]!=0)throw new IllegalStateException("Held mode did not restore");Toolscreen.LOGGER.info("TOOLSCREEN_MEASUREMENT_RESUME_PASS");}if(stage==22||stage==23){double mode=NativeBridge.snapshot()[0];Toolscreen.hotkey(66,0,1);Toolscreen.hotkey(66,0,0);if(!Toolscreen.suspended()||NativeBridge.snapshot()[0]!=mode||view[0]!=game.getWindow().getWidth()||view[1]!=game.getWindow().getHeight())throw new IllegalStateException("Normal screen leaked controls");Toolscreen.LOGGER.info("TOOLSCREEN_SCREEN_CONTEXT_PASS stage={}",stage);}}
}
